func (valSet *defaultSet) QuorumSize() int {
	//c.currentLogger(true, nil).Trace("WBFT: confirmation Formula used ceil(2N/3)")
	return int(math.Ceil(float64(valSet.Size()) - valSet.F()))
}

func (c *Core) broadcastRoundChange(round *big.Int) {
	c.newRetrySendingRoundChangeTimer()
	logger := c.currentLogger(true, nil)

	// Validates new round corresponds to current view
	cv := c.currentView()
	if cv.Round.Cmp(round) > 0 {
		logger.Warn("WBFT: invalid past target round", "current", cv.Round, "target", round)
		return
	}

	roundChange := wbfmessage.NewRoundChange(c.current.Sequence(), round, c.current.preparedRound, c.current.preparedBlock)

	// Sign message
	encodedPayload, err := roundChange.EncodePayloadForSigning()
	if err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to encode ROUND-CHANGE message", "err", err)
		return
	}
	signature, err := c.backend.Sign(encodedPayload)
	if err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to sign ROUND-CHANGE message", "err", err)
		return
	}
	roundChange.SetSignature(signature)

	// Extend ROUND-CHANGE message with PREPARE justification
	if c.WBFTPreparedPrepares != nil {
		roundChange.Justification = c.WBFTPreparedPrepares
		withMsg(logger, roundChange).Debug("WBFT: extended ROUND-CHANGE message with PREPARE justification", "justification", roundChange.Justification)
	}

	// RLP-encode message
	data, err := rlp.EncodeToBytes(roundChange)
	if err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to encode ROUND-CHANGE message", "err", err)
		return
	}

	withMsg(logger, roundChange).Info("WBFT: broadcast ROUND-CHANGE message", "payload", hexutil.Encode(data))

	// Broadcast RLP-encoded message
	if err = c.backend.Broadcast(c.valSet, roundChange.Code(), data); err != nil {
		withMsg(logger, roundChange).Error("WBFT: failed to broadcast ROUND-CHANGE message", "err", err)
		return
	}
}

func (rcs *roundChangeSet) Add(r *big.Int, msg wbfmessage.WBFTMessage, preparedRound *big.Int, preparedBlock wbft.Proposal, prepareMessages []*wbfmessage.Prepare, quorumSize int) error {
	rcs.mu.Lock()
	defer rcs.mu.Unlock()

	round := r.Uint64()
	if rcs.roundChanges[round] == nil {
		rcs.roundChanges[round] = newWBFTMsgSet(rcs.validatorSet)
	}
	if err := rcs.roundChanges[round].Add(msg); err != nil {
		return err
	}

	if preparedRound != nil && (rcs.highestPreparedRound[round] == nil || preparedRound.Cmp(rcs.highestPreparedRound[round]) > 0) {
		roundChange := msg.(*wbfmessage.RoundChange)
		if hasMatchingRoundChangeAndPrepares(roundChange, prepareMessages, quorumSize) == nil {
			rcs.highestPreparedRound[round] = preparedRound
			rcs.highestPreparedBlock[round] = preparedBlock
			rcs.prepareMessages[round] = prepareMessages
		}
	}

	return nil
}

func (c *Core) handlePreprepareMsg(preprepare *wbfmessage.Preprepare) error {
	logger := c.currentLogger(true, preprepare)

	logger = logger.New("proposal.number", preprepare.Proposal.Number().Uint64(), "proposal.hash", preprepare.Proposal.Hash().String())

	c.logger.Debug("WBFT: handle PRE-PREPARE message")

	// Validates PRE-PREPARE message comes from current proposer
	if !c.valSet.IsProposer(preprepare.Source()) {
		logger.Warn("WBFT: ignore PRE-PREPARE message from non proposer", "proposer", c.valSet.GetProposer().Address())
		return errNotFromProposer
	}

	// Reject if sequence ≠ proposal number
	if preprepare.Sequence.Uint64() != preprepare.Proposal.Number().Uint64() {
		logger.Warn("WBFT: ignore PRE-PREPARE with mismatched sequence and proposal number")
		return errInvalidPreparedBlock
	}

	// Validates PRE-PREPARE message justification
	if preprepare.Round.Uint64() > 0 {
		if err := isJustified(preprepare.Proposal, preprepare.JustificationRoundChanges, preprepare.JustificationPrepares, c.valSet.QuorumSize()); err != nil {
			logger.Warn("WBFT: invalid PRE-PREPARE message justification", "err", err)
			return errInvalidPreparedBlock
		}
	}

	// Validates PRE-PREPARE block proposal we received
	if duration, err := c.backend.Verify(preprepare.Proposal); err != nil {
		// if it's a future block, we will handle it again after the duration
		if err == consensus.ErrFutureBlock {
			logger.Info("WBFT: PRE-PREPARE block proposal is in the future (will be treated again later)", "duration", duration)

			// start a timer to re-input PRE-PREPARE message as a backlog event
			c.timerMu.Lock()
			c.stopFuturePreprepareTimer()
			c.futurePreprepareTimer = time.AfterFunc(duration, func() {
				_, validator := c.valSet.GetByAddress(preprepare.Source())
				c.sendEvent(backlogEvent{
					src: validator,
					msg: preprepare,
				})
			})
			c.timerMu.Unlock()
		} else {
			logger.Warn("WBFT: invalid PRE-PREPARE block proposal", "err", err)
		}

		return err
	}

	// Here is about to accept the PRE-PREPARE
	if c.state == StateAcceptRequest {
		c.logger.Debug("WBFT: accepted PRE-PREPARE message")

		// Re-initialize ROUND-CHANGE timer
		c.newRoundChangeTimer()
		c.consensusTimestamp = time.Now()

		// Update current state
		c.current.SetPreprepare(preprepare)
		c.setState(StatePreprepared)

		// Broadcast prepare message to other validators
		c.broadcastPrepare()
	}

	return nil
}

func (c *Core) handlePrepareMsg(prepare *wbfmessage.Prepare) error {
	logger := c.currentLogger(true, prepare).New()

	logger.Debug("WBFT: handle PREPARE message", "prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Check digest
	if prepare.Digest != c.current.Proposal().Hash() {
		logger.Warn("WBFT: invalid PREPARE message digest")
		return errInvalidMessage
	}

	// Check prepareSeal
	block, ok := c.current.Proposal().(*types.Block)
	if !ok {
		logger.Warn("WBFT: failed to cast proposal from PREPARE message to *types.Block")
		return errInvalidMessage
	}

	if verifySeal(c.valSet, block.Header(), uint32(prepare.CommonPayload.Round.Uint64()), SealTypePrepare,
		prepare.PrepareSeal, prepare.Source()) != nil {
		logger.Warn("WBFT: failed to verify seal from PREPARE message", "number", block.Header().Number, "from", prepare.Source())
		return errInvalidMessage
	}

	// Save PREPARE messages
	if err := c.current.WBFTPrepares.Add(prepare); err != nil {
		logger.Error("WBFT: failed to save PREPARE message", "err", err)
		return err
	}

	logger = logger.New("prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Change to "Prepared" state if we've received quorum of PREPARE messages
	// and we are in earlier state than "Prepared"
	if (c.current.WBFTPrepares.Size() >= c.valSet.QuorumSize()) && c.state.Cmp(StatePrepared) < 0 {
		logger.Info("WBFT: received quorum of PREPARE messages")

		// Accumulates PREPARE messages
		c.current.preparedRound = c.currentView().Round
		c.WBFTPreparedPrepares = make([]*wbfmessage.Prepare, 0)
		for _, m := range c.current.WBFTPrepares.Values() {
			c.WBFTPreparedPrepares = append(
				c.WBFTPreparedPrepares,
				wbfmessage.NewPrepareWithSigAndSource(
					m.View().Sequence, m.View().Round, m.(*wbfmessage.Prepare).Digest, m.Signature(), m.Source(), m.(*wbfmessage.Prepare).PrepareSeal))
		}

		if c.current.Proposal() != nil && c.current.Proposal().Hash() == prepare.Digest {
			logger.Trace("WBFT: PREPARE message matches proposal", "proposal", c.current.Proposal().Hash(), "prepare", prepare.Digest)
			c.current.preparedBlock = c.current.Proposal()
		}

		c.setState(StatePrepared)
		c.broadcastCommit()
	} else {
		logger.Trace("WBFT: accepted PREPARE messages")
	}

	return nil
}

func (c *Core) handleCommitMsg(commit *wbfmessage.Commit) error {
	logger := c.currentLogger(true, commit)

	logger.Debug("WBFT: handle COMMIT message", "commits.count", c.current.WBFTCommits.Size(), "quorum", c.valSet.QuorumSize())

	// Check digest
	if commit.Digest != c.current.Proposal().Hash() {
		logger.Warn("WBFT: invalid COMMIT message digest", "digest", commit.Digest, "proposal", c.current.Proposal().Hash().String())
		return errInvalidMessage
	}

	// Check commitSeal
	block, ok := c.current.Proposal().(*types.Block)
	if !ok {
		logger.Warn("WBFT: failed to cast proposal from COMMIT message to *types.Block")
		return errInvalidMessage
	}

	if verifySeal(c.valSet, block.Header(), uint32(commit.CommonPayload.Round.Uint64()), SealTypeCommit,
		commit.CommitSeal, commit.Source()) != nil {
		logger.Warn("WBFT: failed to verify seal from COMMIT message", "number", block.Header().Number, "from", commit.Source())
		return errInvalidMessage
	}

	// Add to received msgs
	if err := c.current.WBFTCommits.Add(commit); err != nil {
		c.logger.Error("WBFT: failed to save COMMIT message", "err", err)
		return err
	}

	logger = logger.New("commits.count", c.current.WBFTCommits.Size(), "quorum", c.valSet.QuorumSize())

	// If we reached threshold
	if c.current.WBFTCommits.Size() >= c.valSet.QuorumSize() {
		logger.Info("WBFT: received quorum of COMMIT messages")
		c.commitWBFT()
	} else {
		logger.Trace("WBFT: accepted new COMMIT messages")
	}

	return nil
}

func (c *Core) IsCurrentProposal(blockHash common.Hash) bool {
	c.currentMutex.RLock()
	defer c.currentMutex.RUnlock()
	return c.current != nil && c.current.pendingRequest != nil && c.current.pendingRequest.Proposal.Hash() == blockHash
}

func (c *Core) startNewRound(round *big.Int) {
	c.currentMutex.Lock()
	defer c.currentMutex.Unlock()

	var logger log.Logger
	if c.current == nil {
		logger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		logger = c.currentLogger(false, nil)
	}
	logger = logger.New("target.round", round)

	roundChange := false

	// Try to get last proposal
	lastProposal, lastProposer := c.backend.LastProposal()
	if lastProposal != nil {
		logger = logger.New("lastProposal.number", lastProposal.Number().Uint64(), "lastProposal.hash", lastProposal.Hash())
	}

	logger.Debug("WBFT: initialize new round")

	if c.current == nil {
		logger.Debug("WBFT: start at the initial round")
	} else if lastProposal.Number().Cmp(c.current.Sequence()) >= 0 {
		diff := new(big.Int).Sub(lastProposal.Number(), c.current.Sequence())
		sequenceMeter.Mark(new(big.Int).Add(diff, common.Big1).Int64())

		if !c.consensusTimestamp.IsZero() {
			consensusTimer.UpdateSince(c.consensusTimestamp)
			c.consensusTimestamp = time.Time{}
		}
		logger.Debug("WBFT: catch up last block proposal")
	} else if lastProposal.Number().Cmp(big.NewInt(c.current.Sequence().Int64()-1)) == 0 {
		if round.Cmp(common.Big0) == 0 {
			// same seq and round, don't need to start new round
			logger.Debug("WBFT: same round, no need to start new round")
			return
		} else if round.Cmp(c.current.Round()) < 0 {
			logger.Warn("WBFT: next round is inferior to current round")
			return
		}
		roundChange = true
	} else {
		logger.Warn("WBFT: next sequence is before last block proposal")
		return
	}

	var oldLogger log.Logger
	if c.current == nil {
		oldLogger = c.logger.New("old.round", -1, "old.seq", 0)
	} else {
		oldLogger = c.logger.New("old.round", c.current.Round().Uint64(), "old.sequence", c.current.Sequence().Uint64(), "old.state", c.state.String(), "old.proposer", c.valSet.GetProposer())
	}

	if c.current != nil && round.Cmp(c.current.Round()) > 0 {
		roundMeter.Mark(new(big.Int).Sub(round, c.current.Round()).Int64())
	}

	// Create next view
	var newView *wbft.View
	var nextValSet wbft.ValidatorSet
	if roundChange {
		newView = &wbft.View{
			Sequence: new(big.Int).Set(c.current.Sequence()),
			Round:    new(big.Int).Set(round),
		}
		nextValSet = c.valSet
	} else {
		newView = &wbft.View{
			Sequence: new(big.Int).Add(lastProposal.Number(), common.Big1),
			Round:    new(big.Int),
		}
		nextValSet = c.backend.Validators(lastProposal)

		// Add extra seal that contributed to consensus
		c.addEffectiveSealToExtraSeal()
	}

	// New snapshot for new round
	c.updateRoundState(nextValSet, newView, roundChange)

	// Calculate new proposer
	c.valSet.CalcProposer(lastProposer, newView.Round.Uint64())
	c.setState(StateAcceptRequest)

	// Update RoundChangeSet by deleting older round messages
	if round.Uint64() == 0 {
		c.WBFTPreparedPrepares = nil
		c.roundChangeSet = newRoundChangeSet(c.valSet)
		c.ClearExtraSeals(lastProposal.Number())
	} else {
		// Clear earlier round messages
		c.roundChangeSet.ClearLowerThan(round)
	}
	c.roundChangeSet.NewRound(round)

	c.backend.NotifyNewRound(round)

	// the order of NotifyNewRound() and newRoundChangeTimer() does not matter on actual consensus, but
	// it matters on multi-engine test, so we keep the order as it is
	c.newRoundChangeTimer()

	oldLogger.Info("WBFT: start new round", "next.round", newView.Round, "next.seq", newView.Sequence, "next.proposer", c.valSet.GetProposer(), "next.valSet", c.valSet.List(), "next.size", c.valSet.Size(), "next.IsProposer", c.IsProposer())
}

func (valSet *defaultSet) Size() int {
	valSet.validatorMu.RLock()
	defer valSet.validatorMu.RUnlock()
	return len(valSet.validators)
}

func (valSet *defaultSet) List() []wbft.Validator {
	valSet.validatorMu.RLock()
	defer valSet.validatorMu.RUnlock()
	return valSet.validators
}
